class Unit(Enum):
    """
    Physical unit string (e.g. "knots", "m", "°C") for a physical metric; `null` when the metric is DIMENSIONLESS (an index / category / phase / score / factor / multiplier / proxy — NOT a percentage; probabilities/likelihoods are 0..1 dimensionless by design, so decide client-side whether to render ×100). Never inferred from the metric name — read from the server's canonical metric→unit registry. Closed set of current + reserved unit tokens (null = dimensionless index); adding a token is a contract change, so consumers may map exhaustively. `MED` = Minimal Erythemal Dose (the standard erythemal UV-exposure unit; carried by the `uv_dose_med` metric). `%` is RESERVED: no dimension emits it today (humidity / cloud-cover / precip-probability are not yet exposed as dimensions) — it is in the enum now so its first real use is not a breaking change. Convention note: current tokens mix spelled-out ("knots", "seconds") and symbolic ("m", "km", "°C") forms; any future normalisation of that would itself be breaking, so map the tokens verbatim.
    """

    knots = "knots"
    degrees = "degrees"
    m = "m"
    km = "km"
    seconds = "seconds"
    field_C = "°C"
    mm_h = "mm/h"
    mm = "mm"
    kg_m_ = "kg/m³"
    hPa = "hPa"
    MED = "MED"
    field_ = "%"
    NoneType_None = None


